import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  process.on('workerMessage', (value: any, src: any) => console.log('main workerMessage', JSON.stringify(value), src));
  const sender = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    wt.parentPort.on('message', (go) => {
      wt.postMessageToThread(0, { from: 'sender', go }).then((r) => { wt.parentPort.postMessage('sender resolved ' + r); }, (e) => { wt.parentPort.postMessage('sender ' + e.code); });
    });
    wt.parentPort.postMessage('ready');
  `, { eval: true });
  let message: any = undefined;
  await new Promise<void>((resolve: () => void): void => { sender.once('message', (m: any) => { message = m; resolve(); }); });
  sender.postMessage('go');
  await new Promise<void>((resolve: () => void): void => { sender.once('message', (m: any) => { message = m; resolve(); }); });
  console.log('from sender:', message);
  await sender.terminate();
  console.log('done');
}
